    />

    return (
        <>
            <div className="view-goals">
                <div className="goals-card">
                <h1 className="goals-title">Goals page demo</h1>

                <div className="goals">
                    {goals.map((goal) => {
                        return (
                            <GoalItem 
                                key={goal.id}
                                id={goal.id}
                                goalName={goal.goalname}
                                goalDesc={goal.goaldesc}
                                deleteGoal={DeleteGoal}
                            />
                        );
                    })}
                </div>
                </div>

                <AddGoal 
                    userId={1}
                    onGoalAdded={fetchGoals}
                />
            </div>
        </>
    );
}
